import re
import sys
from pathlib import Path

LINE_RE = re.compile(
    r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) ERROR \[([^\]]+)\] (.*)$"
)


def parse_errors(path):
    rows = []
    with open(path, encoding="utf-8") as f:
        for line in f:
            m = LINE_RE.match(line.rstrip("\r\n"))
            if m:
                rows.append({"time": m[1], "module": m[2], "message": m[3]})
    return rows


def format_table(rows):
    lines = ["| time | module | message |", "|---|---|---|"]
    for r in rows:
        msg = r["message"].replace("|", "\\|")
        lines.append(f"| {r['time']} | {r['module']} | {msg} |")
    return "\n".join(lines)


def main(argv):
    if len(argv) != 2:
        print(f"usage: {Path(argv[0]).name} <logfile>", file=sys.stderr)
        return 2
    print(format_table(parse_errors(argv[1])))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
